#include <memory>
#include <vector>
#include <string>

std::vector<std::string> load_names() {
    auto names = std::make_unique<std::vector<std::string>>();
    names->push_back("ada");
    names->push_back("grace");
    return *names;  // moves the vector out; unique_ptr frees nothing twice
}

int main() {
    auto v = load_names();  // no copy of the strings
    return v.size() == 2 ? 0 : 1;
}
